def classify_nids_signal(suricata_hit, flow_anomaly_score):
    if suricata_hit and suricata_hit['severity'] == 1:
        return 'HIGH_CONFIDENCE_EXPLOIT'
    if flow_anomaly_score >= 0.85:
        return 'BEHAVIORAL_ANOMALY'
    return 'BENIGN_BASELINE'

def compute_ja4_prefix(tls_ver, sni_present, cipher_count, ext_count, alpn):
    sni_char = 'd' if sni_present else 'i'
    return f't{tls_ver}{sni_char}{cipher_count:02d}{ext_count:02d}{alpn[:2]}'

def should_ebpf_bypass_elephant_flow(dst_port, pkt_count, known_backup_ips, dst_ip):
    # Sample/bypass verified high-volume backup flows after handshake
    return dst_ip in known_backup_ips and dst_port == 443 and pkt_count > 1000

def beacon_periodicity_score(intervals_sec):
    if len(intervals_sec) < 10:
        return 0.0
    mean_i = sum(intervals_sec) / len(intervals_sec)
    std_i = math.sqrt(sum((x - mean_i) ** 2 for x in intervals_sec) / len(intervals_sec))
    cv = std_i / max(mean_i, 1e-6)  # Low coefficient of variation = periodic beacon
    return round(max(0.0, 1.0 - cv), 3)

def shannon_entropy(s):
    if not s:
        return 0.0
    counts = Counter(s)
    n = len(s)
    return -sum((c / n) * math.log2(c / n) for c in counts.values())

def correlate_kill_chain(host_alerts, window_sec=3600):
    tactics = {a['mitre_tactic'] for a in host_alerts}
